// High cyclomatic complexity function - needs careful testing
function calculateDiscount(user, items, coupon, isPremium) {
  let discount = 0;

  // Branch 1: Premium user gets base discount
  if (isPremium) {
    discount += 10;

    // Branch 2: Premium with >5 items
    if (items.length > 5) {
      discount += 5;
    }
  }

  // Branch 3: Valid coupon
  if (coupon && coupon.isValid()) {
    discount += coupon.value;

    // Branch 4: Coupon with weekend purchase
    if (isWeekend()) {
      discount += 5;
    }
  }

  // Branch 5: First-time user
  if (user.isFirstPurchase) {
    discount += 15;
  }

  // Branch 6: Cap at 50%
  if (discount > 50) {
    discount = 50;
  }

  return discount;
}
// Cyclomatic complexity = 7 (high)
